select eldervale_private.quest_arc_put('a3c0b000-0002-4000-8000-000000000004',$q${"chain":"arc-frontier","order":4,"published":true,"objectives":[],"key":"arc-frontier-4","name":"The Wardstone Pact","questPoints":3,"difficulty":"Experienced","length":"Long","giver":"a3c0a000-0002-4000-8000-000000000001","icon":"willowLogs","requirements":{"quests":["arc-frontier-3"],"qp":16,"skills":{"firemaking":{"level":35,"boostable":false},"woodcutting":{"level":35,"boostable":false},"defence":{"level":30,"boostable":false}}},"description":"The great wardfire on the Rimeback summit has been dark for a generation. If it burns, the whole north will see it. So will the Pale Shepherd.","dialogue":{"offer":[{"who":"npc","text":"Rusk says a fire and a song drive this thing back. Fine. I have the biggest fire in the north, if anyone can light it."},{"who":"npc","text":"The summit beacon on the Rimeback. Dark since my mother was Marshal. The trolls hold the crags around it now."},{"who":"npc","text":"Take Pell. He hates heights. It builds character."}],"progress":[{"who":"npc","text":"Can I see the summit burning? I cannot. Climb."}],"complete":[{"who":"npc","text":"The summit burns. The whole north can see it from here. My mother would have wept. I nearly did."},{"who":"npc","text":"Ottilie says Hearthmoor will rebuild under that light. And the cave the Shepherd hides in is open to us. Take these boots; they belonged to the last Marshal who climbed it."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"pact_broken":true},"lines":[{"who":"npc","text":"The summit burns, and the troll caves are marked on my map. A bounty is a bounty."},{"who":"npc","text":"I will not pretend it sits easy. Take these boots; the cave the Shepherd hides in is open to us."}]}],"stages":[{"id":"willow","journal":"Marshal Vossberg wants the great wardfire on the Rimeback summit lit again. Pell will carry the tinder if I bring ten willow logs; he is terrified of heights.","npc":"a3c0a000-0002-4000-8000-000000000002","objectives":[{"type":"collect","target":"willowLogs","amount":10,"label":"Bring Pell ten willow logs"}],"dialogue":{"advance":[{"who":"npc","text":"Ten logs. Up there. With me. I am going to be brave about this. Starting... now. No. Now."}]}},{"id":"summit","journal":"Pell is coming, slowly, with the tinder. I have to reach the old summit beacon on the Rimeback crags, through the trolls that hold them.","onEnter":{"cutscene":"climb"},"objectives":[{"type":"visit","x":306,"z":-346,"radius":5,"amount":1,"label":"Reach the summit beacon on the Rimeback"}]},{"id":"kindle","journal":"The summit beacon is a great bowl of black iron, full of snow. I need to clear it and get a proper fire going.","objectives":[{"type":"xp","skill":"firemaking","amount":300,"label":"Kindle the great wardfire (Firemaking XP)"},{"type":"xp","skill":"woodcutting","amount":200,"label":"Cut kindling on the summit (Woodcutting XP)"}]},{"id":"pact","journal":"The great wardfire is burning. The trolls came out of the crags to stare at it, and Hask came up behind them, breathless. They want to talk.","npc":"a3c0a000-0002-4000-8000-000000000006","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000006","amount":1,"label":"Meet Hask and the trolls below the summit","dialogue":[{"who":"npc","text":"They say: the fire is a hearth. They say: warm-walker made a hearth for everyone."},{"who":"npc","text":"They offer a pact. They will guard the summit fire and the pass, if Winterwatch lets their young winter by the wardfires."}]}],"dialogue":{"choice":[{"who":"npc","text":"Or. The Marshal pays a bounty for every troll cave found. They have just shown you where theirs are. Your choice, warm-walker."}]},"choices":[{"id":"pact","label":"Swear the pact. The fires are for everyone.","flags":{"pact_sworn":true},"dialogue":[{"who":"npc","text":"They are... singing. Badly. It is the hearth song. I think it is the first time they have ever sung it happy."}]},{"id":"bounty","label":"Report the troll caves for the Marshal’s bounty.","flags":{"pact_broken":true},"dialogue":[{"who":"npc","text":"Then go. And do not come back to my camp. They will not forget this, and neither will I."}]}]},{"id":"hearthmoor","journal":"I have made my decision about the trolls. Reeve Ottilie should hear that the great wardfire is burning over Hearthmoor before I report to the Marshal.","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000005","amount":1,"label":"Tell Reeve Ottilie the summit burns","dialogue":[{"who":"npc","text":"I saw it! The whole valley saw it. We are rebuilding by its light. Starting with the bakery, obviously."}]}]}],"cutscenes":{"climb":{"name":"The Rimeback climb","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"The Rimeback","subtitle":"Above Hearthmoor","ms":2400},{"say":{"who":"npc","name":"Pell Ashby","text":"I am fine. This is fine. Do not look down. I looked down. Why did I look down."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"summit":{"name":"The great wardfire","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000001","distance":5,"height":2.2,"angle":30}},{"title":"The great wardfire","subtitle":"The Rimeback summit","ms":2400},{"say":{"who":"npc","name":"Marshal Ingrid Vossberg","text":"There it is. Every farm from here to the pass can see it. And somewhere up there, something cold has just noticed."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000001","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"summit"},"journalDone":"I carried willow up the Rimeback with Pell and lit the great wardfire on the summit for the first time in a generation. Hearthmoor is rebuilding by its light, and the Marshal opened the way to the cave where the Pale Shepherd hides.","journalVariants":[{"ifFlags":{"pact_sworn":true},"text":"I swore a pact with the trolls: they guard the fires, and their young winter by them."},{"ifFlags":{"pact_broken":true},"text":"I reported the troll caves for the Marshal’s bounty."}],"gold":1200,"xp":{"firemaking":20000,"woodcutting":15000,"defence":15000},"items":{"armor:pathfinderBoots":1},"lamps":[{"amount":15000,"minLevel":30,"label":"Summit lamp (any skill of level 30+)"}],"unlocks":[{"type":"area","id":"area.frontier-grotto","label":"Rimeheart Grotto, under the Rimeback"},{"type":"shortcut","id":"shortcut.frontier-ice-stair","label":"Rimeback ice-stair from Hearthmoor (Agility 35)"},{"type":"flag","id":"frontier.summit_lit","label":"The great wardfire burns on the Rimeback"},{"type":"dialogue","id":"dialogue.frontier-hask-pact","label":"Hask keeps the pact","npc":"a3c0a000-0002-4000-8000-000000000006","ifFlags":{"pact_sworn":true},"lines":[{"who":"npc","text":"The young trolls winter by the Eastwatch fire now. Pell taught them to hum. Everyone regrets it."}]},{"type":"dialogue","id":"dialogue.frontier-hask-broken","label":"Hask will not speak to you","npc":"a3c0a000-0002-4000-8000-000000000006","ifFlags":{"pact_broken":true},"lines":[{"who":"npc","text":"Go away, bounty-walker. The caves are empty now. You made sure of that."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0002-4000-8000-000000000005',$q${"chain":"arc-frontier","order":5,"published":true,"objectives":[],"key":"arc-frontier-5","name":"The Pale Shepherd","questPoints":5,"difficulty":"Master","length":"Very long","giver":"a3c0a000-0002-4000-8000-000000000001","icon":"custom_qa_wardstone","requirements":{"quests":["arc-frontier-1","arc-frontier-2","arc-frontier-3","arc-frontier-4"],"qp":34,"skills":{"firemaking":{"level":45,"boostable":false},"woodcutting":{"level":45,"boostable":false},"agility":{"level":40,"boostable":false},"prayer":{"level":35,"boostable":false}},"combat":60},"description":"The Pale Shepherd has seen the great wardfire. Every night the cold creeps further down the Rimeback. Marshal Vossberg wants it finished, in its own cave.","dialogue":{"offer":[{"who":"npc","text":"Frost on the inside of my windows. In my own hall. It is coming down to look at us."},{"who":"npc","text":"Rusk says it hides in the Rimeheart Grotto, under the crags, with its frozen flock. Fire and the hearth song."},{"who":"player","text":"Then I’ll bring both."},{"who":"npc","text":"Take the braziers up with you. Pell has volunteered. Pell does not know he has volunteered yet."}],"progress":[{"who":"npc","text":"The cold is in the well now. Hurry."}],"complete":[{"who":"npc","text":"Its crook. Ice that will not melt, even here by the fire. So it is truly gone."},{"who":"npc","text":"Hearthmoor is a village again, the pass is open, and the north will not freeze this winter. Take the Aegis of the last Warden. And this stone, cut from the summit fire: it will always bring you home to Hearthmoor."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"pact_sworn":true},"lines":[{"who":"npc","text":"Its crook. And Hask tells me trolls carried the braziers to the cave mouth for you. Trolls! Carrying fire!"},{"who":"npc","text":"Take the Aegis of the last Warden, and this stone from the summit fire: it will always bring you home to Hearthmoor."}]}],"stages":[{"id":"rally","journal":"The Pale Shepherd is creeping down from the peaks. Marshal Vossberg wants it destroyed in its cave, the Rimeheart Grotto under the Rimeback. Hask may know the way in.","objectives":[{"type":"talk","target":"a3c0a000-0002-4000-8000-000000000006","amount":1,"label":"Ask Hask about the Rimeheart Grotto","dialogue":[{"who":"npc","text":"The cave breathes cold. The Shepherd keeps frozen trolls inside, standing, like statues that walk."},{"who":"npc","text":"Fire and the song. If you carry the fire, the song will find you."}]}]},{"id":"braziers","journal":"Hask says the Shepherd keeps frozen trolls as its flock. I need fuel for the braziers we will carry in: six maple logs, for Pell to pack.","npc":"a3c0a000-0002-4000-8000-000000000002","objectives":[{"type":"collect","target":"mapleLogs","amount":6,"label":"Bring Pell six maple logs for the braziers"}],"dialogue":{"advance":[{"who":"npc","text":"Braziers packed. I will stay at the cave mouth and keep them burning. Bravely. From the cave mouth."}]}},{"id":"descend","journal":"Pell is keeping the braziers burning at the Rimeheart cave mouth. Time to go in.","onEnter":{"cutscene":"grotto"},"objectives":[{"type":"visit","x":2224,"z":3004,"radius":7,"amount":1,"label":"Enter the frozen galleries of Rimeheart Grotto"}]},{"id":"thralls","journal":"The frozen galleries are full of the Shepherd’s flock: trolls frozen mid-stride and made to walk.","objectives":[{"type":"event","event":"death","targets":["a3c0a000-0002-4000-9000-000000000006","a3c0a000-0002-4000-9000-000000000007"],"amount":2,"label":"Shatter the frozen thralls"}]},{"id":"pillars","journal":"Beyond the thralls stand three pillars of blue ice, humming with the Shepherd’s cold. The hearth song says “the hearth that waits behind the door”: I should warm each pillar in turn before the Shepherd’s door.","objectives":[{"type":"visit","x":2242,"z":2988,"radius":2.5,"amount":1,"label":"Warm the western ice pillar"},{"type":"visit","x":2250,"z":2988,"radius":2.5,"amount":1,"label":"Warm the eastern ice pillar"},{"type":"visit","x":2246,"z":2998,"radius":2.5,"amount":1,"label":"Warm the pillar by the door"}]},{"id":"shepherd","journal":"The pillars cracked and the door to the sanctum groaned open. The Pale Shepherd is waiting inside.","onEnter":{"cutscene":"shepherd"},"objectives":[{"type":"kill","target":"a3c0a000-0002-4000-9000-000000000008","amount":1,"label":"Defeat the Pale Shepherd"},{"type":"have","target":"custom_qa_shepherds_crook","amount":1,"label":"Take the Pale Shepherd’s crook"}]},{"id":"home","journal":"The Pale Shepherd is gone. Its crook of unmelting ice should go to Marshal Vossberg in Winterwatch.","objectives":[{"type":"collect","target":"custom_qa_shepherds_crook","amount":1,"label":"Give the crook to Marshal Vossberg"}]}],"cutscenes":{"grotto":{"name":"Rimeheart Grotto","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"Rimeheart Grotto","subtitle":"Under the Rimeback","ms":2400},{"say":{"who":"npc","name":"Pell Ashby","text":"I will be right here. Feeding the fire. Not crying. Go on."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"shepherd":{"name":"The Pale Shepherd","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000006","distance":5,"height":2.2,"angle":30}},{"title":"The Pale Shepherd","subtitle":"The Rimeheart sanctum","ms":2400},{"say":{"who":"npc","name":"Hask the Troll-Tongue","text":"(Far behind you, faintly, somebody is singing the hearth song. Badly. In Troll.)"},"shot":{"around":"a3c0a000-0002-4000-8000-000000000006","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"thaw":{"name":"The thaw","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0002-4000-8000-000000000005","distance":5,"height":2.2,"angle":30}},{"title":"The long winter ends","subtitle":"Hearthmoor","ms":2400},{"say":{"who":"npc","name":"Reeve Ottilie Marsh","text":"Roofs on every house. Bread in every oven. And the wardfire over all of it. Welcome home, whoever you are."},"shot":{"around":"a3c0a000-0002-4000-8000-000000000005","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"thaw"},"journalDone":"I carried fire into Rimeheart Grotto, shattered the Pale Shepherd’s frozen flock, warmed its ice pillars by the hearth song and destroyed the Shepherd in its sanctum. The long winter is over: Hearthmoor is rebuilt, and a wardstone from the summit fire will always bring me back there.","journalVariants":[{"ifFlags":{"pact_sworn":true},"text":"The trolls carried the braziers to the cave for me, keeping the pact."}],"gold":5000,"xp":{"firemaking":60000,"woodcutting":40000,"prayer":30000,"agility":30000},"items":{"custom_qa_wardstone":1,"shield:wardensAegis":1},"lamps":[{"amount":20000,"minLevel":40,"label":"Wardfire lamp (any skill of level 40+)"}],"unlocks":[{"type":"teleport","id":"teleport.hearthmoor","label":"Wardstone of Hearthmoor: the rebuilt village","x":258,"z":-294},{"type":"area","id":"area.frontier-fold","label":"The Shepherd’s Fold: the Pale Shepherd, Unbound (harder mode)"},{"type":"area","id":"lair:rimecoil_cavern","label":"Rimecoil Cavern: Frostmaw, the Glacier Wyrm, wakes in the thaw"},{"type":"flag","id":"frontier.hearthmoor_rebuilt","label":"Hearthmoor is rebuilt"},{"type":"dialogue","id":"dialogue.frontier-ottilie-5","label":"Hearthmoor rebuilt","npc":"a3c0a000-0002-4000-8000-000000000005","lines":[{"who":"npc","text":"Roofs, ovens, a well that does not freeze. The children have named a goat after you. It bites. It is an honour."}]},{"type":"dialogue","id":"dialogue.frontier-vossberg-5","label":"The Marshal’s thanks","npc":"a3c0a000-0002-4000-8000-000000000001","lines":[{"who":"npc","text":"The beacons burn, the pass is open, and nothing herds the winter but the winter. You did that."},{"who":"npc","text":"Though with the thaw, the ice cleft by the Frostmaw eyrie has opened. Something big is breathing in there. Take the Aegis when you go."}]},{"type":"dialogue","id":"dialogue.frontier-rusk-5","label":"Mother Rusk’s blessing","npc":"a3c0a000-0002-4000-8000-000000000003","lines":[{"who":"npc","text":"I sang the hearth song in the square last night and everyone joined in. Even the Marshal. She sings like a gate."}]},{"type":"dialogue","id":"dialogue.frontier-pell-5","label":"Pell, hero of the cave mouth","npc":"a3c0a000-0002-4000-8000-000000000002","lines":[{"who":"npc","text":"I kept the braziers burning for six hours. Alone. In a cave. I am telling everyone. I have already told everyone."}]}]}$q$::jsonb);

commit;
